{
  "typography": {
    "caption": {
      "fontWeight": 400,
      "letterSpacing": 0
    },
    "detail": {
      "fontWeight": 400,
      "letterSpacing": 0
    },
    "body": {
      "fontWeight": 400,
      "letterSpacing": 0
    },
    "label": {
      "fontWeight": 500,
      "letterSpacing": 0
    },
    "title": {
      "fontWeight": 600,
      "letterSpacing": 0
    },
    "headline": {
      "fontWeight": 600,
      "letterSpacing": 0
    },
    "display": {
      "fontWeight": 600,
      "letterSpacing": 0
    }
  },
  "dimension": {
    "size": {
      "hit": {
        "pointer": 0,
        "touch": 44
      },
      "density": {
        "pointer": {
          "pad": 12,
          "gap": 12
        },
        "touch": {
          "pad": 12,
          "gap": 12
        }
      },
      "item": {
        "pointer": {
          "inset": 4,
          "pad": 8
        },
        "touch": {
          "inset": 8,
          "pad": 8
        }
      },
      "control": {
        "pointer": {
          "padding": 8,
          "gap": 8
        },
        "touch": {
          "padding": 8,
          "gap": 8
        }
      },
      "height": {
        "pointer": {
          "sm": 24,
          "md": 28,
          "lg": 32
        },
        "touch": {
          "sm": 32,
          "md": 40,
          "lg": 48
        }
      }
    },
    "stroke": {
      "hairline": 1,
      "control": 1
    },
    "focus": {
      "style": "halo",
      "width": 3,
      "offset": 0
    },
    "icon": {
      "pointer": {
        "sm": 12,
        "md": 16,
        "lg": 20
      },
      "touch": {
        "sm": 16,
        "md": 20,
        "lg": 24
      }
    }
  },
  "controls": {
    "button": {
      "corner": {
        "sm": "control",
        "md": "control",
        "lg": "control"
      },
      "selected": {
        "face": {
          "finish": "accent"
        },
        "ink": {
          "color": "primary-foreground"
        }
      },
      "secondary": {
        "face": {
          "finish": "raised"
        },
        "ink": {
          "color": "foreground"
        },
        "edge": {
          "finish": "raised",
          "field": "borderColor"
        },
        "hover": {
          "finish": "hover"
        }
      },
      "outline": {
        "edge": {
          "color": "border"
        }
      },
      "destructive": {
        "edge": {
          "color": "destructive",
          "alpha": 0.32
        }
      },
      "shade": "raised"
    },
    "badge": {
      "corner": "control"
    },
    "field": {
      "edge": {
        "sides": true,
        "color": {
          "color": "input"
        },
        "bottom": {
          "color": "input"
        }
      },
      "corner": {
        "bottom": "control"
      },
      "focus": {
        "line": false,
        "width": 3,
        "color": {
          "color": "brand"
        }
      },
      "disabled": {
        "face": "keep"
      }
    },
    "choice": {
      "size": {
        "pointer": 16,
        "touch": 22
      },
      "box": {
        "pointer": 16,
        "touch": 20
      },
      "corner": {
        "pointer": 5,
        "touch": 7
      },
      "face": {
        "light": {
          "color": "field"
        },
        "dark": {
          "color": "input",
          "alpha": 0.3
        }
      },
      "shade": "inset",
      "edge": {
        "width": 1,
        "color": {
          "light": {
            "color": "input"
          },
          "dark": {
            "color": "foreground",
            "alpha": 0.2
          }
        },
        "disabled": {
          "light": {
            "color": "input"
          },
          "dark": {
            "color": "foreground",
            "alpha": 0.4
          }
        }
      },
      "checked": {
        "face": {
          "finish": "accent"
        }
      },
      "radio": {
        "checked": {
          "face": {
            "finish": "accent"
          },
          "edge": "none"
        }
      },
      "mark": {
        "size": {
          "pointer": 6,
          "touch": 8
        },
        "hover": "none",
        "pressed": "none"
      },
      "halo": "none"
    },
    "switch": {
      "track": {
        "pointer": [
          36,
          20
        ],
        "touch": [
          44,
          24
        ]
      },
      "small": {
        "track": {
          "pointer": [
            28,
            16
          ],
          "touch": [
            36,
            20
          ]
        },
        "knob": {
          "pointer": 12,
          "touch": 16
        }
      },
      "edge": {
        "off": 1,
        "on": 1,
        "color": {
          "color": "border"
        }
      },
      "knob": {
        "size": {
          "pointer": 16,
          "touch": 20
        },
        "on": "same",
        "hover": "same",
        "pressed": "same"
      }
    },
    "slider": {
      "rail": {
        "pointer": 6,
        "touch": 8
      },
      "band": {
        "pointer": 20,
        "touch": 32
      },
      "face": {
        "color": "track"
      },
      "shade": "inset",
      "edge": {
        "color": {
          "color": "border"
        },
        "width": "control"
      },
      "knob": {
        "size": {
          "pointer": 14,
          "touch": 20
        },
        "pressed": {
          "pointer": 14,
          "touch": 32
        },
        "face": {
          "finish": "knob"
        },
        "edge": "none"
      },
      "mark": {
        "size": 0,
        "hover": 0,
        "pressed": 0
      },
      "brightens": true
    },
    "progress": {
      "height": 6,
      "line": 0,
      "face": {
        "color": "track"
      },
      "shade": "inset",
      "edge": {
        "color": {
          "color": "border"
        },
        "width": "control"
      }
    },
