    },
    "popup": {
      "corner": "container"
    },
    "tooltip": {
      "face": {
        "finish": "inverse"
      },
      "ink": {
        "finish": "inverse",
        "field": "foreground"
      },
      "edge": {
        "finish": "inverse",
        "field": "borderColor"
      },
      "shade": "inverse"
