        "face": {
          "finish": "accent"
        }
      }
    },
    "list": {
      "item": {
        "highlight": {
          "tint": "brand"
        },
        "edge": {
          "color": "brand",
          "alpha": 0.3
        }
      }
    },
    "menubar": {
      "bar": {
        "finish": "card"
