    },
    "tabs": {
      "track": {
        "face": {
          "color": "inset"
        },
        "edge": {
          "color": "border"
        },
        "corner": "full"
      }
    },
    "well": {
      "edge": {
        "color": "border"
      }
    },
    "disabled": {
      "face": "keep",
      "ink": "keep",
      "edge": "keep"
    }
  },
  "shape": {
    "curve": "continuous"
  },
  "state": {
    "press-scale": 0.97,
    "overlay": {
      "hover": 0,
      "pressed": 0
    },
    "pressed-opacity": 0.7,
    "rest-opacity": 0.5,
    "disabled": {
      "content": 0.5
    }
  },
  "motion": {
    "fast": {
      "duration": 150,
      "timingFunction": "out-cubic"
    },
    "default": {
      "duration": 250,
      "timingFunction": "out-cubic"
    },
    "slow": {
      "duration": 350,
      "timingFunction": "out-cubic"
    },
    "state": {
      "duration": 120,
      "timingFunction": "out-cubic"
    }
  },
  "finishes": {
